import{_ as i,l as s,o as e,c as d,v as o,p as c,x as r,d as l,i as n,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"写时复制","description":"","frontmatter":{"title":"写时复制","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cow-fork.md","filePath":"cs/cow-fork.md","lastUpdated":1789023840000}'),h={name:"cs/cow-fork.md"};function f(m,a,_,k,u,E){const t=s("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="写时复制" tabindex="-1">写时复制 <a class="header-anchor" href="#写时复制" aria-label="Permalink to &quot;写时复制&quot;">​</a></h1><div class="epigraph"><p>fork 之后父子共享物理页并标只读；谁先写，谁才得到一份私有拷贝。</p><footer>—— 据 Rashid 等对 Mach 虚存的表述；Unix fork 语义在 Bach 与 MOS 中的整理</footer></div><p><a href="/cs/overcommit">上一课</a>让物理帧成为稀缺品。<a href="/cs/process-image">进程映像</a>的 fork 若立刻复制全部用户页，缺页与置换会被自己打爆，而子进程往往马上 <code>exec</code> 丢掉刚复制的空间。缺口是<strong>写时复制（COW）</strong>：共享只读，写时再拆。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>POSIX fork 语义是「子进程地址空间是父的副本」。副本可以是逻辑的：页表指向同一帧，两端页表项去掉写权限。写故障时内核判断是 COW 而非真保护错，分配新帧、拷贝、恢复写权限。缺口不是新的调页，而是把「复制」从 fork 时刻挪到第一次写。</p><p>本课不把 <code>vfork</code> 与 <code>clone</code> 的全部标志写完。</p><p><span class="marginnote">引用计数记有多少页表指向该帧。降到一且本应可写时，可直接恢复写权限，不必拷贝。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>fork：复制页表项，COW 位 + 只读，帧引用加一。任一方写入 → 缺页 → 若 COW 则拷贝；若引用已为一则只改权限。<code>exec</code> 拆掉旧映射，COW 页若仅剩另一进程，引用下降。与<a href="/cs/demand-paging">按需调页</a>叠：尚未触碰的文件页仍可双方共享同一文件映射，直到写。</p>',9)),(e(),c(p,null,{default:r(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FORK%5B%22fork%3A%20%E5%85%B1%E4%BA%AB%E5%8F%AA%E8%AF%BB%22%5D%20--%3E%20WRITE%5B%22%E5%86%99%E6%95%85%E9%9A%9C%22%5D%0A%20%20WRITE%20--%3E%20COPY%5B%22%E6%96%B0%E5%B8%A7%E6%8B%B7%E8%B4%9D%22%5D%0A%20%20COPY%20--%3E%20PRIV%5B%22%E7%A7%81%E6%9C%89%E5%8F%AF%E5%86%99%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>COW 让「创建进程」与「占用两倍物理内存」解耦，调度可以很快跑子进程。管道课的亲缘进程因此便宜。内核必须区分：文本本就只读，写是 SIGSEGV；数据页的只读可能是 COW。这是缺页处理里的类型字段，不是新的 MMU 周期。</p><p>置换仍可淘汰 COW 页：若干净且来自文件，丢掉即可；若匿名且仍共享，要小心写回与引用，实现复杂，主干只承认「共享页淘汰更挑剔」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入跨进程的 <code>userfaultfd</code> 等机制，不把容器快照的全部 COW 文件系统（如 overlay）混进进程页。也不讲硬件的两阶段缺页性能数字。安全课会关心是否漏恢复写位，本课假定实现正确。</p><p>KSM 等合并相同页是另一方向的共享，本课不把去重当 fork 语义。</p><p>内核在写故障路径上必须序列化引用计数，避免两份都以为自己该独占。</p><p>后课默认：fork 后页按写拆分。把文件直接接进地址空间、不一定走 <code>read</code> 拷贝，下一课 mmap。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>fork 的副本语义可用共享只读 + 写时拷贝实现。</li><li>真保护错与 COW 故障要在缺页里分开。</li><li>文件映射进虚空间是 mmap 的缺口。</li><li>出处：Mach 虚存（Rashid et al.）；Bach, <em>The Design of the UNIX Operating System</em>；Tanenbaum <em>MOS</em>。</li></ul>',10))])}const B=i(h,[["render",f]]);export{C as __pageData,B as default};
